package vn.hust.restaurant.view;
import java.awt.*;import javax.swing.*;import vn.hust.restaurant.config.AppContext;import vn.hust.restaurant.model.DashboardStats;
public class DashboardPanel extends JPanel implements Refreshable{private final AppContext ctx;private final JLabel revenue=new JLabel("-"),invoices=new JLabel("-"),tables=new JLabel("-"),kitchen=new JLabel("-"),stock=new JLabel("-");public DashboardPanel(AppContext c){ctx=c;setLayout(new BorderLayout(15,15));setBorder(BorderFactory.createEmptyBorder(20,20,20,20));JLabel h=new JLabel("TỔNG QUAN HÔM NAY");h.setFont(h.getFont().deriveFont(Font.BOLD,24));add(h,BorderLayout.NORTH);JPanel grid=new JPanel(new GridLayout(1,5,15,15));grid.add(card("Doanh thu",revenue));grid.add(card("Hóa đơn",invoices));grid.add(card("Bàn đang dùng",tables));grid.add(card("Món chờ bếp",kitchen));grid.add(card("Nguyên liệu sắp hết",stock));add(grid,BorderLayout.CENTER);refresh();}private JPanel card(String t,JLabel v){JPanel p=new JPanel(new BorderLayout());p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createEtchedBorder(),BorderFactory.createEmptyBorder(18,18,18,18)));JLabel l=new JLabel(t,SwingConstants.CENTER);v.setHorizontalAlignment(SwingConstants.CENTER);v.setFont(v.getFont().deriveFont(Font.BOLD,22));p.add(l,BorderLayout.NORTH);p.add(v,BorderLayout.CENTER);return p;}public void refresh(){Ui.run(this,()->{DashboardStats s=ctx.reports.dashboard();revenue.setText(String.format("%,.0f đ",s.todayRevenue()));invoices.setText(String.valueOf(s.todayInvoices()));tables.setText(String.valueOf(s.occupiedTables()));kitchen.setText(String.valueOf(s.waitingKitchenItems()));stock.setText(String.valueOf(s.lowStockItems()));});}}
